'use strict';
(function(root){const imgs={};function asset(name){if(!imgs[name]){const im=new Image();im.src='rpg-fx/'+name+'.png';imgs[name]=im;}return imgs[name];}
function image(p,name,x,y,w,h,angle=0,crop=null){const im=asset(name);if(!im.complete||!im.naturalWidth)return;p.save();p.translate(x,y);p.rotate(angle);if(crop)p.drawImage(im,...crop,-w/2,-h/2,w,h);else p.drawImage(im,-w/2,-h/2,w,h);p.restore();}
function atlas(p,name,frame,x,y,w,h){const im=asset(name+'-atlas');if(!im.complete||!im.naturalWidth)return;const fw=im.naturalWidth/4,fh=im.naturalHeight/2,n=Math.max(0,Math.min(7,Math.floor(frame)));p.drawImage(im,(n%4)*fw,Math.floor(n/4)*fh,fw,fh,x-w/2,y-h/2,w,h);}
function lines(p,points,color,width=2){p.strokeStyle=color;p.lineWidth=width;p.beginPath();points.forEach(([x,y],i)=>i?p.lineTo(x,y):p.moveTo(x,y));p.stroke();}
function cross(p,x,y,size,alpha=1){p.save();p.globalAlpha*=alpha;p.fillStyle='#f7ecc1';p.fillRect(x-size*.12,y-size*.5,size*.24,size);p.fillRect(x-size*.38,y-size*.18,size*.76,size*.23);p.fillStyle='#fffdf0';p.fillRect(x-1,y-size*.4,2,size*.7);p.restore();}
function talisman(p,x,y,size=30,angle=0,charge=0){p.save();p.translate(x,y);p.rotate(angle);p.fillStyle='#b0925f';p.fillRect(-size*.27,-size*.53,size*.54,size*1.06);p.fillStyle='#f1dfad';p.fillRect(-size*.23,-size*.49,size*.46,size*.98);p.fillStyle='#ad423e';p.fillRect(-size*.19,-size*.39,size*.38,size*.11);lines(p,[[-size*.11,-size*.15],[size*.1,-size*.1],[-size*.06,size*.05],[size*.12,size*.17],[-size*.1,size*.3]],'#ac403d',Math.max(1,size*.06));if(charge){p.fillStyle='#e4a95b';p.fillRect(-size*.22,size*.38,size*.44,size*.06);}p.restore();}
function sparks(p,x,y,t,n=9,r=60,color='#f3d995'){p.fillStyle=color;for(let i=0;i<n;i++){const a=i*2.399,d=r*Math.min(1,t*2)*( .65+(i%3)*.17);p.fillRect(x+Math.cos(a)*d,y+Math.sin(a)*d*.55-12*t,2+(i%2),3);}}
function fist(p,x,y,t,index=0,scale=1){const q=Math.max(0,Math.sin(Math.min(1,t/.32)*Math.PI));image(p,'monk-fist-authored',x-22+q*18,y-17+(index%2?5:-5),48*scale,22*scale,index%2?.14:-.14,[420,215,938,463]);sparks(p,x,y-17,t,5,25);}
function chapel(p,z,t){p.save();if(z.kind==='pilgrim'){p.globalAlpha*=.55;atlas(p,'priest-chapel',3+Math.floor(t*3)%3,z.x,z.y-45,z.radius*1.65,z.radius*1.5);p.restore();return;}p.restore();p.save();p.translate(z.x,z.y);const r=z.radius;p.strokeStyle=z.kind==='pilgrim'?'#ebddb0':'#a8c4a5';p.lineWidth=2;p.globalAlpha*=.6;for(let side of [-1,1]){lines(p,[[side*r,-4],[side*r*.72,-r*.3],[side*r*.35,-r*.48],[0,-r*.54]],p.strokeStyle,2);lines(p,[[side*r,4],[side*r*.72,r*.3],[side*r*.35,r*.48],[0,r*.54]],p.strokeStyle,2);}for(let i=0;i<4;i++){const a=i*Math.PI/2;cross(p,Math.cos(a)*r*.85,Math.sin(a)*r*.45-7,16,.7);}if(z.kind==='pilgrim'){cross(p,0,-48,25,.75);for(let side of [-1,1])lines(p,[[side*14,-32],[side*29,-45],[side*36,-11]],'#f6e6b2',2);}else{for(let side of [-1,1]){lines(p,[[side*25,0],[side*25,-48],[0,-70],[-side*25,-48]],'#b8d4b4',2);}}p.restore();}
function sealField(p,z,t){const r=z.radius;p.save();p.globalAlpha*=.65;atlas(p,'priest-seal',3+Math.floor(t*4)%3,z.x,z.y-6,r*2.15,r*1.25);p.restore();lines(p,[[z.x-r,z.y],[z.x,z.y-r*.54],[z.x+r,z.y],[z.x,z.y+r*.54],[z.x-r,z.y]],'#ccab71',1.5);for(let i=0;i<4;i++){const a=i*Math.PI/2;talisman(p,z.x+Math.cos(a)*r,z.y+Math.sin(a)*r*.54,24,Math.sin(t*3+i)*.08,1);}}
function draw(p,f,t,D){if(f.heroId!==10)return false;if(t<0||t>2.5)return true;const o=f.from||f,x=o.x,y=o.y-25,tx=f.x,ty=f.y-22,slot=f.slot||0,cell=f.cell||0;const skill=D?.skills.find(s=>s.heroId===10&&s.cell===cell&&s.slot===slot),kind=f.priestKind||skill?.actions[0]?.kind||'';p.save();p.globalAlpha*=Math.max(0,Math.min(1,(2.1-t)*2));
if(!f.phase){if([1,3].includes(cell)){const n=slot===2?0:slot===0?3:slot===3?cell===3?6:1:2;for(let i=0;i<n;i++){const at=t-i*(cell===3?.1:.16);if(at>=0&&at<.35)fist(p,x+18+i*3,y+5,at,i,slot===3?1.3: .8);}if(kind==='rising-kick'){lines(p,[[x-8,y+14],[x+17,y-18],[x+39,y-30]],'#ecdba5',3);}if(kind==='monk-breath'){for(let i=0;i<3;i++)lines(p,[[x-16+i*16,y+30],[x-19+i*16,y+10-t*10],[x-16+i*16,y-10-t*15]],'#b0d9c5',1);}if(kind==='perfect-rhythm'){for(let i=0;i<4;i++)cross(p,x+(i-1.5)*13,y-30,7,Math.max(0,1-t));}}
else if(cell===6){if(kind==='binding-talisman')talisman(p,x+20+Math.sin(t*9)*3,y-4,26,-.3);else if(kind==='fourfold-barrier'){for(let i=0;i<4;i++)talisman(p,tx+Math.cos(i*Math.PI/2)*48,ty+Math.sin(i*Math.PI/2)*24,22,i*.1);}else if(kind==='ritual-interrupt'){talisman(p,tx,ty,42,-.2);lines(p,[[tx-27,ty-23],[tx+27,ty+23]],'#fff0bf',3);}else{for(let i=0;i<6;i++)talisman(p,tx+Math.cos(i*Math.PI/3)*70,ty+Math.sin(i*Math.PI/3)*38,25,t*.2);lines(p,[[tx-55,ty],[tx+55,ty],[tx,ty-45],[tx,ty+45]],'#e5c48d',2);}}
else if(cell===4){const n=slot+1;for(let i=0;i<n;i++){const at=t-i*.09;if(at>=0&&at<1){cross(p,slot===2?x+(i-1)*19:tx+(i-(n-1)/2)*23,slot===2?y-15:ty-25,20+slot*5,1-at);}}if(slot===1||slot===3)for(let i=0;i<4+slot;i++){const at=t-i*.04;if(at>0&&at<.6)lines(p,[[tx+(i-3)*9,ty+12],[tx+(i-3)*8-5,ty-10-at*32],[tx+(i-3)*9+3,ty-35-at*42]],'#f8e6b9',2);}}
else{if(kind==='pilgrim-chapel')atlas(p,'priest-chapel',Math.min(3,t*5),x,y-20,160,150);if(kind==='priest-wave')for(let i=0;i<3;i++)lines(p,[[x-65-i*10,y+i*12],[x,y-10+i*12],[x+65+i*10,y+i*12]],'#fff2c8',2);if(kind==='priest-arrow')lines(p,[[x-20,y],[x+40,y],[x+28,y-8],[x+40,y],[x+28,y+8]],'#fff1bf',2);if(kind==='anchored-chapel')lines(p,[[x-38,y+20],[x-38,y-36],[x,y-65],[x+38,y-36],[x+38,y+20]],'#b5d2b7',2);if(kind==='miracle-release')for(let i=0;i<3;i++)lines(p,[[x+(i-1)*22,y+25],[x+(i-1)*22,y-30-t*40]],'#fff1cf',3);const n=slot===3?5:slot===2?4:cell===5?3:1;for(let i=0;i<n;i++){const a=i*Math.PI*2/n+t*.25;cross(p,x+Math.cos(a)*(n===1?10:24+slot*4),y+Math.sin(a)*13-(slot===0?15:0),slot===3?25:16,Math.max(0,1-t/1.4));}if(slot===2)lines(p,[[x-23,y+18],[x-23,y-22],[x,y-38],[x+23,y-22],[x+23,y+18]],cell===5?'#efdc9a':'#b7d1b9',2);if(slot===1)sparks(p,x,y,t,6+cell,35+cell*3);}
}else if(/fist|palm|monk-impact|champion-finish|jab/.test(kind)){fist(p,tx,ty+20,t,f.index||0,/finish|impact/.test(kind)?1.6:1);if(kind==='champion-finish')for(let i=0;i<4;i++)lines(p,[[tx-45,ty+i*7],[tx+45,ty+i*7-8]],'#f6d9a4',2);}
else if(kind==='rising-kick'||kind==='kick-landing'){sparks(p,tx,ty,t,12,85);lines(p,[[tx-40,ty+12],[tx-10,ty-9],[tx+10,ty-48],[tx+27,ty-65]],'#edc786',3);}
else if(/seal-break|exorcist-cross/.test(kind)){const n=kind==='exorcist-cross'?8:3;for(let i=0;i<n;i++){const a=i*Math.PI*2/n;talisman(p,tx+Math.cos(a)*(30+t*80),ty+Math.sin(a)*(18+t*40),25,t+i*.3);}if(kind==='exorcist-cross'){atlas(p,'priest-seal',Math.min(7,t*9),tx,ty,320,200);}if(kind==='exorcist-cross')image(p,'exorcist-rite-authored',tx,ty-35,250,205,0,[163,49,1037,1101]);else lines(p,[[tx-35,ty-35],[tx+35,ty+35],[tx+35,ty-35],[tx-35,ty+35]],'#f4dab2',3);}
else if(/brand|judgment|white-flame/.test(kind)){if(kind!=='white-flame'){atlas(p,'priest-brand',Math.min(7,t*10),tx,ty-18,kind==='judgment-stamp'?140:72,kind==='judgment-stamp'?155:80);}const n=kind==='white-flame'?6:3+(f.stacks||0);for(let i=0;i<n;i++){const at=t+(i%3)*.12,dx=(i-(n-1)/2)*9;lines(p,[[tx+dx,ty+20],[tx+dx-5,ty-Math.sin(at*8+i)*10],[tx+dx+4,ty-30-Math.abs(Math.sin(at*5))*30]],i%2?'#fff7d8':'#e0ba71',2);}if(kind!=='white-flame')cross(p,tx,ty-10,kind==='judgment-stamp'?70:35,1-t/1.8);}
else if(kind==='miracle-pillar'){image(p,'highpriest-miracle-authored',tx,ty-65,250,240,0,[121,18,1070,1166]);for(let i=0;i<3+(f.grace||0);i++)cross(p,tx+Math.cos(i*2.399)*90,ty-30+Math.sin(i*2.399)*30-t*25,14);}
else if(kind==='holy-wave'){image(p,'priest-wave-authored',x,y+15,Math.min(460,80+t*420),Math.min(200,40+t*180),0,[27,157,1719,602]);}
else if(kind==='dawn-impact'){cross(p,tx,ty-45+t*30,80);sparks(p,tx,ty,t,14,130);}
else if(/pulse/.test(kind)){const r=f.radius||160;for(let i=0;i<(kind==='seal-pulse'?4:8);i++){const a=i*Math.PI/4;if(kind==='seal-pulse')talisman(p,tx+Math.cos(a)*r*.7,ty+Math.sin(a)*r*.35,18,t);else cross(p,tx+Math.cos(a)*r*.65,ty+Math.sin(a)*r*.33-t*12,12,1-t);}}
else if(/hit/.test(kind)){if(kind==='talisman-hit')talisman(p,tx,ty,34,0,1);else cross(p,tx,ty,kind==='arrow-hit'?44:27);sparks(p,tx,ty,t,7,45);}
else if(/ward/.test(kind)){for(let side of [-1,1])lines(p,[[x+side*27,y+24],[x+side*32,y-27],[x,y-47]],'#e8dcad',2);cross(p,x,y-17,26);}
else if(/mend|grace|prayer|breath|rhythm/.test(kind)){for(let i=0;i<4;i++)cross(p,x+(i-1.5)*13,y+20-t*30-i*4,10+(i%2)*3,1-t/1.5);}
else if(/plant|open/.test(kind)){cross(p,x,y-25,35,1-t);sparks(p,x,y,t,12,90);}
p.restore();return true;}
function state(p,g,time){if(g.s.active!==10||!g.c?.priest)return;const s=g.c.priest,c=g.c;for(const z of s.zones){p.save();p.globalAlpha*=Math.min(1,z.life);if(z.kind==='seal')sealField(p,z,time);else chapel(p,z,time);p.restore();}for(const shot of s.shots){p.save();if(shot.kind==='talisman')talisman(p,shot.x,shot.y,25,(shot.angle||0)+Math.sin(time*12)*.2);else{const len=shot.kind==='arrow'?34:shot.kind==='grace'?22:15;p.translate(shot.x,shot.y);p.rotate(shot.angle||0);lines(p,[[-len,0],[len*.5,0],[len*.15,-5],[len*.5,0],[len*.15,5]],shot.kind==='grace'?'#c5f1df':'#f8e8b7',3);cross(p,0,0,9);}p.restore();}for(const e of c.enemies.filter(e=>e.hp>0)){if(e.priestBrand)atlas(p,'priest-brand',2,e.x,e.y-66,30+e.priestBrand*4,35+e.priestBrand*4);if(e.priestSeal)for(let i=0;i<e.priestSeal;i++)talisman(p,e.x+(i-(e.priestSeal-1)/2)*13,e.y-60,17,.1*(i-1));}if(s.ward>0){p.save();p.globalAlpha*=.65;lines(p,[[c.x-24,c.y-5],[c.x-30,c.y-45],[c.x,c.y-70],[c.x+30,c.y-45],[c.x+24,c.y-5]],'#d1e2bc',2);p.restore();}if([1,3,5].includes(g.h.cell)){p.fillStyle='#e6d5a2';p.font='bold 9px sans-serif';p.textAlign='center';p.fillText(g.h.cell===5?'은총 '+s.grace+'/6':'연계 '+s.combo+'/8',c.x,c.y-78);}}
root.RPG_PRIEST_FX={draw,state};})(typeof window!=='undefined'?window:globalThis);
